// ============================================
// LANGUAGE DETECTION & MANAGEMENT
// ============================================

function detectLanguage() {
    let lang = localStorage.getItem('qx_language');
    if (lang && LANGUAGES[lang]) return lang;
    const browserLang = navigator.language || navigator.language || 'en';
    const langCode = browserLang.split('-')[0].toLowerCase();
    const langMap = { 'en': 'en', 'ur': 'ur', 'ar': 'ar', 'tr': 'tr' };
    return langMap[langCode] || 'en';
}

function getTranslation(key, lang = null) {
    const currentLang = lang || detectLanguage();
    const translations = TRANSLATIONS[currentLang] || TRANSLATIONS.en;
    return translations[key] || TRANSLATIONS.en[key] || key;
}

