// ============================================
// GET ACTUAL TRADE PROFIT/LOSS
// ============================================
function getTradeProfitLoss() {
    try {
        const profitEl = document.querySelector('.position__header-money.--green, .position__header-money.--red, .position__header-money');
        if (profitEl) {
            let text = profitEl.textContent || '';
            const match = text.match(/[\d,]+\.\d+/);
            if (match) {
                let profit = parseFloat(match[0].replace(/,/g, ''));
                if (profitEl.classList.contains('--red') || (text.includes('$') && text.indexOf('$') > 0 && !text.startsWith('$'))) {
                    profit = -profit;
                }
                return profit;
            }
        }
        
        const balEl = document.querySelector('.Zt1hG');
        if (balEl && initialBal > 0) {
            const bal = safeNum(balEl.textContent);
            return bal - initialBal;
        }
        
        return 0;
    } catch (e) {
        return 0;
    }
}

// ============================================
// DETECT NEW TRADE RESULT
// ============================================
function detectTradeResult() {
    try {
        const balanceEl = document.querySelector(selectors.userBalance);
        if (!balanceEl) return null;
        
        const currentBalance = safeNum(balanceEl.textContent);
        if (currentBalance <= 0) return null;
        
        if (lastKnownBalance === null) {
            lastKnownBalance = currentBalance;
            return null;
        }
        
        const balanceChange = currentBalance - lastKnownBalance;
        lastKnownBalance = currentBalance;
        
        if (Math.abs(balanceChange) < 0.01) return null;
        
        return balanceChange;
    } catch (e) {
        return null;
    }
}

// ============================================
// GREEN LINE
// ============================================
function updateAutoGreenLine() {
    try {
        const balanceEl = document.querySelector(selectors.userBalance);
        const expandEl = document.querySelector(selectors.expand);

        if (!expandEl) return;

        const balance = safeNum(balanceEl?.textContent);

        if (!balance || balance <= 0) {
            expandEl.style.width = '0%';
            currentExpandPercent = 0;
            expandEl.style.background = '#0faf59';
            return;
        }

        const mode = localStorage.getItem(KEY_GREEN_MODE) || 'auto';
        
        if (mode === 'manual') {
            const manualPercent = Number(localStorage.getItem(KEY_SLIDER) || 50);
            currentExpandPercent = Math.max(0, Math.min(100, manualPercent));
            expandEl.style.width = currentExpandPercent + '%';
            expandEl.style.background = '#0faf59';
            return;
        }

        const startBalance = Number(localStorage.getItem(KEY_INIT) || 0);

        if (!startBalance || startBalance <= 0) {
            expandEl.style.width = '0%';
            currentExpandPercent = 0;
            expandEl.style.background = '#0faf59';
            return;
        }

        const diff = balance - startBalance;
        const lossThreshold = 15000;

        if (diff < 0 && Math.abs(diff) >= lossThreshold) {
            expandEl.style.width = '0%';
            currentExpandPercent = 0;
            expandEl.style.background = '#0faf59';
            return;
        }

        if (diff < 0) {
            currentExpandPercent = 1;
            expandEl.style.width = '1%';
            expandEl.style.background = '#0faf59';
            return;
        }

        if (diff === 0) {
            currentExpandPercent = 0;
            expandEl.style.width = '0%';
            expandEl.style.background = '#0faf59';
            return;
        }

        let profitPercent = (diff / startBalance) * 100;
        profitPercent = Math.max(0, Math.min(100, profitPercent));
        currentExpandPercent = profitPercent;
        expandEl.style.width = profitPercent + '%';
        expandEl.style.background = '#0faf59';

    } catch (e) {
        console.error('Green line error:', e);
    }
}

