function getRankNumber(element) {
    if (!element) return null;
    const text = element.textContent || element.innerText || '';
    const match = text.match(/\d+/);
    return match ? parseInt(match[0], 10) : null;
}

function createCustomCard(rank, name, flag, avatar, formattedAmount, sign) {
    const div = document.createElement('div');
    div.className = 'CYmPX';
    div.setAttribute('data-qx-custom-card', 'true');
    div.setAttribute('data-qx-rank', rank);

    let rankHTML = '';
    let rankClass = 'FdU8g';

    if (rank === 1) {
        rankHTML = '<img src="/profile/images/top-gold.svg" alt="top-gold">';
    } else if (rank === 2) {
        rankHTML = '<img src="/profile/images/top-serebro.svg" alt="top-silver">';
    } else if (rank === 3) {
        rankHTML = '<img src="/profile/images/top-bronza.svg" alt="top-bronze">';
    } else {
        rankClass += ' _0J2mJ';
        rankHTML = '<div class="' + rankClass + '">' + rank + '</div>';
    }

    const rankDisplay = rank <= 3 ? rankHTML + '<div class="' + rankClass + '">' + rank + '</div>' : rankHTML;
    const avatarSrc = avatar || 'https://i.imgur.com/default.png';
    
    const color = sign === 'loss' ? '#ff3e3e' : '#0faf59';

    div.innerHTML = `
        <div class="bCjpw"></div>
        <div class="spCR5">
            <div class="anZcM">${rankDisplay}</div>
            <div class="HPYiu">
                <svg class="${flag}" aria-label="Flag ${flag.replace('flag-', '').toUpperCase()}">
                    <use href="/profile/images/flags.svg#${flag}"></use>
                </svg>
                <div class="QyASJ">
                    <img src="${avatarSrc}" alt="avatar">
                </div>
            </div>
            <div class="hKWVz">${name}</div>
        </div>
        <div class="ePgNa iXGFm" style="color:${color};font-weight:700;">${formattedAmount}</div>
    `;
    return div;
}

function calculateAutoPosition() {
    try {
        let userProfit = 0;
        let profitFound = false;
        let isLoss = false;
        
        const profitSelectors = [
            '.position__header-money.--green',
            '.position__header-money.--red',
            '.position__header-money'
        ];
        
        for (let selector of profitSelectors) {
            const el = document.querySelector(selector);
            if (el) {
                let text = el.textContent || '';
                
                if (el.classList.contains('--red') || (text.includes('$') && text.indexOf('$') > 0 && !text.startsWith('$'))) {
                    isLoss = true;
                }
                
                const match = text.match(/[\d,]+\.\d+/);
                if (match) {
                    userProfit = parseFloat(match[0].replace(/,/g, ''));
                    profitFound = true;
                    break;
                }
                const match2 = text.match(/[\d,]+/);
                if (match2) {
                    userProfit = parseFloat(match2[0].replace(/,/g, ''));
                    profitFound = true;
                    break;
                }
            }
        }
        
        if (!profitFound || userProfit === 0) {
            const balEl = document.querySelector('.Zt1hG');
            if (balEl && initialBal > 0) {
                const bal = safeNum(balEl.textContent);
                const diff = bal - initialBal;
                if (diff !== 0) {
                    userProfit = Math.abs(diff);
                    isLoss = diff < 0;
                    profitFound = true;
                }
            }
        }
        
        if (!profitFound || userProfit === 0) {
            return null;
        }
        
        let effectiveProfit = userProfit;
        if (isLoss) {
            effectiveProfit = -userProfit;
        }
        
        const container = document.querySelector('.tlUK7');
        if (!container) return null;
        
        const cards = container.querySelectorAll('.CYmPX');
        if (!cards.length) return null;
        
        let leaderboardData = [];
        let userCardIndex = -1;
        
        cards.forEach((card, index) => {
            const isOurCard = card.getAttribute('data-qx-custom-card') === 'true';
            
            let amount = 0;
            const amountEl = card.querySelector('.ePgNa');
            if (amountEl) {
                let amountText = amountEl.textContent || '';
                let isCardLoss = false;
                
                if (amountText.includes('$') && amountText.indexOf('$') > 0) {
                    isCardLoss = true;
                }
                
                const match1 = amountText.match(/[\d,]+\.\d+/);
                if (match1) {
                    amount = parseFloat(match1[0].replace(/,/g, ''));
                    if (isCardLoss) amount = -amount;
                } else {
                    const match2 = amountText.match(/[\d,]+/);
                    if (match2) {
                        amount = parseFloat(match2[0].replace(/,/g, ''));
                        if (isCardLoss) amount = -amount;
                    }
                }
            }
            
            if (isOurCard) {
                userCardIndex = index;
            }
            
            leaderboardData.push({
                amount: amount,
                isOur: isOurCard,
                index: index
            });
        });
        
        leaderboardData.sort((a, b) => b.amount - a.amount);
        
        let twentiethPositionProfit = null;
        if (leaderboardData.length >= 20) {
            twentiethPositionProfit = leaderboardData[19].amount;
        } else {
            twentiethPositionProfit = leaderboardData[leaderboardData.length - 1]?.amount || 0;
        }
        
        let userPosition = null;
        
        if (userCardIndex !== -1) {
            for (let i = 0; i < leaderboardData.length; i++) {
                if (leaderboardData[i].isOur) {
                    userPosition = i + 1;
                    break;
                }
            }
        }
        
        if (userPosition === null) {
            const tolerance = 0.01;
            for (let i = 0; i < leaderboardData.length; i++) {
                if (Math.abs(leaderboardData[i].amount - effectiveProfit) < tolerance) {
                    userPosition = i + 1;
                    break;
                }
            }
        }
        
        if (userPosition === null) {
            let position = 1;
            let found = false;
            for (let i = 0; i < leaderboardData.length; i++) {
                if (effectiveProfit > leaderboardData[i].amount) {
                    position = i + 1;
                    found = true;
                    break;
                }
                if (i === leaderboardData.length - 1) {
                    position = leaderboardData.length + 1;
                    found = true;
                }
            }
            if (!found) position = 1;
            userPosition = position;
        }
        
        if (userPosition !== null && userPosition > 0) {
            if (effectiveProfit > 0) {
                if (twentiethPositionProfit !== null && effectiveProfit < twentiethPositionProfit) {
                    return "100+";
                }
                if (userPosition > 100) return "100+";
                return userPosition;
            } else {
                return "100+";
            }
        }
        
        return null;
        
    } catch (e) {
        return null;
    }
}

function getCurrentDisplayAmount() {
    const mode = localStorage.getItem(KEY_UPDATE_MODE) || 'auto';
    const savedLB = JSON.parse(localStorage.getItem(KEY_LB) || '{}');
    const savedSign = localStorage.getItem(KEY_SIGN_MODE) || savedLB.sign || 'profit';
    const savedAmount = Number(savedLB.amount) || 0;
    
    const tradeProfit = getTradeProfitLoss();
    const tradeAmount = Math.abs(tradeProfit);
    
    if (tradeProfit !== 0) {
        const sign = tradeProfit > 0 ? 'profit' : 'loss';
        const amount = tradeAmount;
        const display = sign === 'loss' ? money(amount) + '$' : '$' + money(amount);
        const updatedLB = { ...savedLB, amount: amount, sign: sign };
        localStorage.setItem(KEY_LB, JSON.stringify(updatedLB));
        localStorage.setItem(KEY_SIGN_MODE, sign);
        return { amount, sign, display, source: 'trade' };
    }
    
    if (mode === 'manual') {
        const sign = savedSign;
        const amount = savedAmount;
        const display = sign === 'loss' ? money(amount) + '$' : '$' + money(amount);
        return { amount, sign, display, source: 'manual' };
    }
    
    return { amount: 0, sign: 'profit', display: '$0.00', source: 'none' };
}

function updateLeaderboard() {
    if (isUpdating) return;
    if (!leaderboardActive) return;

    try {
        isUpdating = true;

        const container = document.querySelector('.tlUK7');
        const flagContainer = document.querySelector('.d6ijp');
        const nameContainer = document.querySelector('.ord28.o8xRM');
        const rankContainer = document.querySelector('.c_7BP');

        if (!container || !flagContainer || !nameContainer || !rankContainer) {
            isUpdating = false;
            return;
        }

        const rank = getRankNumber(rankContainer);
        if (!rank || rank < 1 || rank > 20) {
            isUpdating = false;
            return;
        }

        let cards = container.querySelectorAll('.CYmPX');
        if (cards.length < rank) {
            isUpdating = false;
            return;
        }

        const targetCard = cards[rank - 1];
        if (!targetCard) {
            isUpdating = false;
            return;
        }

        const existingCustomCards = container.querySelectorAll('.CYmPX[data-qx-custom-card="true"]');
        existingCustomCards.forEach(card => {
            const cardRank = parseInt(card.getAttribute('data-qx-rank') || '0', 10);
            if (cardRank !== rank && cardRank > 0) {
                const idx = cardRank - 1;
                if (idx >= 0 && savedCards[cardRank]) {
                    try {
                        const currentCards = container.querySelectorAll('.CYmPX');
                        if (currentCards[idx] && currentCards[idx].getAttribute('data-qx-custom-card') === 'true') {
                            container.replaceChild(savedCards[cardRank], currentCards[idx]);
                        }
                    } catch (e) {}
                }
            }
        });

        let flag = customFlag || 'flag-bd';
        if (!customFlag) {
            const svg = flagContainer.querySelector('svg');
            flag = svg ? (svg.className.baseVal || svg.className || 'flag-in') : 'flag-in';
        }

        let name = customName || 'BNDA';
        if (!customName) {
            const nameEl = flagContainer.querySelector('p');
            if (nameEl) {
                const text = nameEl.textContent.trim();
                name = text.startsWith('#') ? 'BNDA' : text;
            }
        }

        const savedLB = JSON.parse(localStorage.getItem(KEY_LB) || '{}');
        const savedSign = localStorage.getItem(KEY_SIGN_MODE) || savedLB.sign || 'profit';
        const savedAmount = Number(savedLB.amount) || 0;
        
        let displayAmount;
        let sign;
        let amount;
        
        const tradeProfit = getTradeProfitLoss();
        
        if (tradeProfit !== 0) {
            amount = Math.abs(tradeProfit);
            sign = tradeProfit > 0 ? 'profit' : 'loss';
            displayAmount = sign === 'loss' ? money(amount) + '$' : '$' + money(amount);
            const updatedLB = { ...savedLB, amount: amount, sign: sign };
            localStorage.setItem(KEY_LB, JSON.stringify(updatedLB));
            localStorage.setItem(KEY_SIGN_MODE, sign);
        } else {
            amount = savedAmount;
            sign = savedSign;
            displayAmount = sign === 'loss' ? money(amount) + '$' : '$' + money(amount);
        }

        if (rank === 1 && sign === 'profit' && amount >= 30000) {
            displayAmount = '$30,000.00+';
        }

        const currentMode = localStorage.getItem(KEY_UPDATE_MODE) || 'auto';
        const updateKey = rank + '|' + name + '|' + flag + '|' + displayAmount + '|' + sign + '|' + currentMode;

        const isOurCard = targetCard && targetCard.getAttribute('data-qx-custom-card') === 'true';

        if (isOurCard && lastUpdateKey === updateKey && currentPosition === rank) {
            isUpdating = false;
            return;
        }

        if (!savedCards[rank]) {
            savedCards[rank] = targetCard.cloneNode(true);
        }

        const customCard = createCustomCard(rank, name, flag, avatarUrl, displayAmount, sign);

        try {
            const freshCards = container.querySelectorAll('.CYmPX');
            const freshTarget = freshCards[rank - 1];
            
            if (freshTarget) {
                container.replaceChild(customCard, freshTarget);
                currentPosition = rank;
                lastUpdateKey = updateKey;
                customCardApplied = true;
            }
        } catch (e) {}

    } catch (e) {
        console.error('updateLeaderboard error:', e);
    }

    isUpdating = false;
}

function forceUpdateLeaderboard() {
    savedCards = {};
    currentPosition = null;
    lastUpdateKey = null;
    customCardApplied = false;
    isUpdating = false;
    
    setTimeout(() => {
        if (leaderboardActive) {
            updateLeaderboard();
            updateFooterPosition();
            updateHeaderAndFooter();
        }
    }, 50);
}

function startLeaderboard() {
    if (leaderboardActive) return;

    leaderboardActive = true;

    let lbUpdatePending = false;
    let headerClickProtection = false;

    function scheduleUpdate() {
        if (!leaderboardActive || lbUpdatePending) return;
        if (headerClickProtection) return;

        lbUpdatePending = true;

        requestAnimationFrame(function() {
            lbUpdatePending = false;
            if (leaderboardActive && !isUpdating && !headerClickProtection) {
                updateLeaderboard();
                updateFooterPosition();
            }
        });
    }

    scheduleUpdate();

    updateTimer = setInterval(function() {
        if (leaderboardActive) {
            scheduleUpdate();
        }
    }, 1000);

    if (mutationObserver) {
        mutationObserver.disconnect();
    }

    mutationObserver = new MutationObserver(function() {
        setTimeout(function() {
            if (!headerClickProtection) {
                scheduleUpdate();
            }
        }, 100);
    });

    mutationObserver.observe(document.body, {
        childList: true,
        subtree: true
    });

    document.addEventListener('click', function(e) {
        if (!leaderboardActive) return;

        const headerElements = ['.xJo6L', '.xQvJK', '.d6ijp', '.ord28', '.c_7BP', 'header', '[role="tab"]', '.P5n2A'];
        let isHeaderClick = false;

        for (let selector of headerElements) {
            if (e.target.closest(selector)) {
                isHeaderClick = true;
                break;
            }
        }

        if (isHeaderClick) {
            headerClickProtection = true;

            setTimeout(function() {
                const container = document.querySelector('.tlUK7');
                if (container) {
                    const cards = container.querySelectorAll('.CYmPX');
                    savedCards = {};
                    cards.forEach((card, index) => {
                        const isOurCard = card.getAttribute('data-qx-custom-card') === 'true';
                        if (!isOurCard) {
                            savedCards[index + 1] = card.cloneNode(true);
                        }
                    });
                }

                setTimeout(function() {
                    headerClickProtection = false;
                    if (leaderboardActive && !isUpdating) {
                        updateLeaderboard();
                        updateFooterPosition();
                    }
                }, 200);
            }, 300);

            return;
        }

        const card = e.target.closest('.tlUK7 .CYmPX');
        if (card) {
            requestAnimationFrame(function() {
                if (leaderboardActive && !isUpdating && !headerClickProtection) {
                    updateLeaderboard();
                    updateFooterPosition();
                }
            });
        }
    }, true);

    window.__qxStopLBTimer = function() {
        lbUpdatePending = false;
        headerClickProtection = false;
    };
}

function updateFooterPosition() {
    try {
        const footer = document.querySelector('.c_7BP');
        if (!footer) return;
        
        const customPos = localStorage.getItem(KEY_CUSTOM_POSITION);
        if (customPos) {
            if (customPos === "100+") {
                footer.innerHTML = '<span style="color:#808080;">Your position: &nbsp;</span><b>100+</b>';
                return;
            }
            const pos = Number(customPos);
            if (pos >= 100) {
                footer.innerHTML = '<span style="color:#808080;">Your position: &nbsp;</span><b>100+</b>';
                return;
            }
            footer.innerHTML = '<span style="color:#808080;">Your position: &nbsp;</span><b>' + pos + '</b>';
            return;
        }
 
        const bal = safeNum(document.querySelector(selectors.userBalance)?.textContent);
        const lossDiff = bal - initialBal;

        if (lossDiff < 0) {
            footer.innerHTML = '<span style="color:#808080;">Your position: &nbsp;</span><b>100+</b>';
            return;
        }    
                      
        const autoPos = calculateAutoPosition();
        if (autoPos !== null && autoPos !== "NaN") {
            let displayPos = autoPos;
            if (autoPos === "100+" || Number(autoPos) >= 100) {
                displayPos = "100+";
            }
            footer.innerHTML = '<span style="color:#808080;">Your position: &nbsp;</span><b>' + displayPos + '</b>';
        } else {
            footer.innerHTML = '<span style="color:#808080;">Your position: &nbsp;</span><b>-</b>';
        }
    } catch(e) {}
}

function stopLeaderboard() {
    leaderboardActive = false;
    customCardApplied = false;

    if (window.__qxStopLBTimer) {
        window.__qxStopLBTimer();
        window.__qxStopLBTimer = null;
    }

    if (updateTimer) {
        clearInterval(updateTimer);
        updateTimer = null;
    }

    if (mutationObserver) {
        mutationObserver.disconnect();
        mutationObserver = null;
    }

    const container = document.querySelector('.tlUK7');
    if (container) {
        const cards = container.querySelectorAll('.CYmPX');
        Object.keys(savedCards).forEach(function(key) {
            const idx = parseInt(key, 10) - 1;
            if (cards[idx] && savedCards[key]) {
                try {
                    container.replaceChild(savedCards[key], cards[idx]);
                } catch (e) {}
            }
        });
    }

    savedCards = {};
    currentPosition = null;
    lastUpdateKey = null;
}

