window.updateQuotexLeaderboard = function(name, flag, amount, avatar, sign, mode) {
    avatarUrl = avatar || avatarUrl || 'https://i.imgur.com/default.png';
    customName = name || customName;
    customFlag = flag ? 'flag-' + flag : customFlag;
    
    if (sign) {
        localStorage.setItem(KEY_SIGN_MODE, sign);
        signMode = sign;
    }
    
    if (mode) {
        localStorage.setItem(KEY_UPDATE_MODE, mode);
        updateMode = mode;
    }

    localStorage.setItem('qx_avatar_url', avatarUrl);
    localStorage.setItem('qx_custom_name', customName);
    localStorage.setItem('qx_custom_flag', customFlag);

    const lbData = {
        name: customName || 'BNDA Enterprise',
        flag: flag || 'in',
        amount: amount || 10000,
        avatar: avatarUrl,
        sign: sign || 'profit',
        mode: mode || 'auto'
    };
    localStorage.setItem('qx_lb_profile', JSON.stringify(lbData));

    forceUpdateLeaderboard();
};

window.stopQuotexLeaderboard = stopLeaderboard;

window.resetQuotexLeaderboard = function() {
    stopLeaderboard();
    localStorage.removeItem('qx_avatar_url');
    localStorage.removeItem('qx_custom_name');
    localStorage.removeItem('qx_custom_flag');
    localStorage.removeItem('qx_lb_profile');
    localStorage.removeItem(KEY_SIGN_MODE);
    localStorage.removeItem(KEY_UPDATE_MODE);
    avatarUrl = null;
    customName = null;
    customFlag = null;
    customCardApplied = false;
    savedCards = {};
    currentPosition = null;
    lastUpdateKey = null;
    signMode = 'profit';
    updateMode = 'auto';
    lastKnownBalance = null;
};

