function activateLiveMode() {
    try {
        if (document.title.includes("Demo"))
            document.title = document.title.replace(/Demo/gi, "Live");

        const listItems = $$(selectors.usermenuListItems);
        if (!listItems.length) return;

        const demoLi = listItems.find(li => li.querySelector('input.r29tN[value="demo"]'));
        const liveLi = listItems.find(li => li.querySelector('input.r29tN[value="live"]'));

        if (!demoLi || !liveLi) return;
        const demoRadio = demoLi.querySelector('input.r29tN[value="demo"]');
        const liveRadio = liveLi.querySelector('input.r29tN[value="live"]');

        if (demoRadio && liveRadio) {
            liveRadio.checked = true;
            demoRadio.checked = false;
            liveRadio.dispatchEvent(new Event('change', { bubbles: true }));
        }

        const demoBalanceElem = demoLi.querySelector("b.YnoT0");
        const liveBalanceElem = liveLi.querySelector("b.YnoT0");

        if (!demoBalanceElem || !liveBalanceElem) return;

        const demoText = localStorage.getItem(KEY_DEMO_TEXT);
        demoBalanceElem.textContent = demoText && demoText.length ? demoText : money(10000);

        const liveBalanceValue = safeNum($(selectors.userBalance)?.textContent) || 0;
        liveBalanceElem.textContent = money(liveBalanceValue);

        demoLi.classList.remove(activeClass);
        liveLi.classList.add(activeClass);

        demoLi.classList.remove("Qx5RW");
        liveLi.classList.add("Qx5RW");

        const demoLink = demoLi.querySelector("a");
        const liveLink = liveLi.querySelector("a");

        if (demoLink) {
            demoLink.removeAttribute("aria-current");
            demoLink.classList.remove("active");
        }

        if (liveLink) {
            liveLink.setAttribute("aria-current", "page");
            liveLink.classList.add("active");
        }

        localStorage.setItem("marketMode", "live");

        if (!initialBal || initialBal <= 0) {
            const savedInitial = Number(localStorage.getItem(KEY_INIT) || 0);

            if (savedInitial > 0) {
                initialBal = savedInitial;
            } else if (liveBalanceValue > 0) {
                initialBal = liveBalanceValue;
                localStorage.setItem(KEY_INIT, String(initialBal));
            }
        }

        updateDropdownBalances();

    } catch (e) {}
}

function updateHeaderAndFooter() {
    try {
        const bal = safeNum($(selectors.userBalance)?.textContent);
        if (isNaN(bal)) return;
        const diff = bal - initialBal;

        const profitEl = $(selectors.positionHeaderMoney);
        if (profitEl) {
            const val = Math.abs(diff);
            if (diff === 0) {
                profitEl.innerText = '$0.00';
            } else if (diff < 0) {
                profitEl.innerText = money(val) + '$';
            } else {
                profitEl.innerText = '$' + money(val);
            }
            profitEl.style.color = diff < 0 ? '#ff3e3e' : '#0faf59';
        }

        updateFooterPosition();

        const data = JSON.parse(localStorage.getItem(KEY_LB) || '{}');
        const mode = localStorage.getItem(KEY_UPDATE_MODE) || 'auto';
        
        if (data.name && data.flag) {
            $$(selectors.lbNameHeader).forEach(box => {
                box.textContent = data.name;
                updateFlag(data.flag);
            });
        }

        const displayInfo = getCurrentDisplayAmount();
        
        $$(selectors.lbMoney).forEach(box => {
            box.textContent = displayInfo.display;
            box.style.color = displayInfo.sign === 'loss' ? '#ff3e3e' : '#0faf59';
        });

        if (displayInfo.source === 'trade') {
            const savedLB = JSON.parse(localStorage.getItem(KEY_LB) || '{}');
            savedLB.amount = displayInfo.amount;
            savedLB.sign = displayInfo.sign;
            localStorage.setItem(KEY_LB, JSON.stringify(savedLB));
            localStorage.setItem(KEY_SIGN_MODE, displayInfo.sign);
            signMode = displayInfo.sign;
        }

    } catch (e) {
        console.error('updateHeaderAndFooter error:', e);
    }
}

function updateLevelInfo() {
    try {
        const bal = safeNum($(selectors.userBalance)?.textContent);
        let levelType = 'standart';

        if (!isNaN(bal)) {
            if (bal > 9999.99) levelType = 'vip';
            else if (bal > 4999.99) levelType = 'pro';
        }

        const iconMap = {
            standart: '/profile/images/spritemap.svg#icon-profile-level-standart',
            pro: '/profile/images/spritemap.svg#icon-profile-level-pro',
            vip: '/profile/images/spritemap.svg#icon-profile-level-vip'
        };

        const href = iconMap[levelType];

        document.querySelectorAll(".nKm6H svg use").forEach(icon => {
            icon.setAttribute("xlink:href", href);
            icon.setAttribute("href", href);
        });

        document.querySelectorAll(".h5aTJ svg use").forEach(icon => {
            icon.setAttribute("xlink:href", href);
            icon.setAttribute("href", href);
        });

        $$(selectors.userName).forEach(nameEl => {
            nameEl.textContent = "Live";
            nameEl.style.color = "#0faf59";
        });

        $$(selectors.levelName).forEach((levelNameElem, i) => {
            const levelProfitElem = $$(selectors.levelProfit)[i];

            if (levelType === "vip") {
                levelNameElem.textContent = "vip:";
                if (levelProfitElem) levelProfitElem.textContent = "+4% profit";
            } else if (levelType === "pro") {
                levelNameElem.textContent = "pro:";
                if (levelProfitElem) levelProfitElem.textContent = "+2% profit";
            } else {
                levelNameElem.textContent = "standard:";
                if (levelProfitElem) levelProfitElem.textContent = "+0% profit";
            }
        });

    } catch (e) {}
}

function updateDropdownBalances() {
    $$(selectors.usermenuListItems).forEach(li => {
        const b = li.querySelector("b");
        if (b) b.textContent = '$' + money(safeNum(b.textContent));
    });
}

function updateFlag(flagCode) {
    if (!flagCode) return;

    flagCode = flagCode.toLowerCase().trim();

    document.querySelectorAll('.d6ijp svg use').forEach(use => {
        use.setAttribute("href", '/profile/images/flags.svg#flag-' + flagCode);
        use.setAttribute("xlink:href", '/profile/images/flags.svg#flag-' + flagCode);
    });

    document.querySelectorAll('.d6ijp svg').forEach(svg => {
        svg.className.baseVal = 'flag-' + flagCode;
        svg.setAttribute("aria-label", 'Flag ' + flagCode.toUpperCase());
    });
}

