                    <div class="qx-preview-amount" id="preview-amount" style="color:${savedSignMode === 'loss' ? '#ff3e3e' : '#0faf59'}">
                        ${savedSignMode === 'loss' ? money(defaultAmount || 0) + '$' : '$' + money(defaultAmount || 0)}
                    </div>
