function boot() {
    activateLiveMode();
    updateHeaderAndFooter();
    updateLevelInfo();
    updateDropdownBalances();

    setInterval(function() {
        updateAutoGreenLine();
    }, 1000);

    setTimeout(function() {
        startLeaderboard();
    }, 1500);

    (function loop() {
        activateLiveMode();
        updateHeaderAndFooter();
        updateLevelInfo();
        updateDropdownBalances();
        requestAnimationFrame(loop);
    })();
}

