const bulkCreateBtn =
    bulkAddOverlay.querySelector("#txBulkAddCreate");


// -----------------------------
// Generate Bulk Transaction Fields
// -----------------------------

function generateBulkTransactionRows() {
    const count = Math.max(
        1,
        Math.min(
            100,
            Number(bulkCountInput.value) || 1
        )
    );
    bulkRowsContainer.innerHTML = "";
    for (let i = 0; i < count; i++) {
        const id = generateTransactionId();
        const now = new Date();
        now.setMinutes(
            now.getMinutes() - now.getTimezoneOffset()
        );
        const dateTime =
            now.toISOString().slice(0, 16);
        const item =
            document.createElement("div");
        item.className =
            "txBulkTransactionItem";
        item.style.cssText = `
            border:1px solid rgba(255,255,255,.15);
            border-radius:10px;
            padding:12px;
            margin:10px 0;
        `;
        item.innerHTML = `
            <div style="
                font-weight:bold;
                margin-bottom:10px;
            ">
                Transaction ${i + 1}
            </div>
            <label>Transaction ID</label>
            <input
                type="text"
                class="txBulkRowId"
                value="${id}"
                style="width:100%;margin:5px 0 10px;"
            >
            <label>Date & Time</label>
            <input
                type="datetime-local"
                class="txBulkRowDate"
                value="${dateTime}"
                style="width:100%;margin:5px 0 10px;"
            >
            <label>Status</label>
            <select
                class="txBulkRowStatus"
                style="width:100%;margin:5px 0 10px;"
            >
                <option value="Successed">
                    Successed
                </option>
                <option value="Waiting confirmation">
                    Processing
                </option>
                <option value="Failed">
                    Failed
                </option>
            </select>
            <label>Type</label>
            <select
                class="txBulkRowType"
                style="width:100%;margin:5px 0 10px;"
            >
                <option value="Deposit">
                    Deposit
                </option>
                <option value="Payout">
                    Withdrawal
                </option>
            </select>
            <label>Payment</label>
            <select
                class="txBulkRowPayment"
                style="width:100%;margin:5px 0 10px;"
            >
                <option value="Binance Pay">
                    Binance Pay
                </option>
                <option value="USDT TRC-20">
                    USDT TRC-20
                </option>
                <option value="USDT BEP-20">
                    USDT BEP-20
                </option>
                <option value="USDT ERC-20">
                    USDT ERC-20
                </option>
                <option value="JazzCash">
                    JazzCash
                </option>
                <option value="EasyPaisa">
                    EasyPaisa
                </option>
                <option value="Bank Transfer">
                    Bank Transfer
                </option>
            </select>
            <label>Amount</label>
            <input
                type="number"
                min="0"
                step="0.01"
                class="txBulkRowAmount"
                placeholder="Enter amount"
                style="width:100%;margin:5px 0 10px;"
            >
        `;
        bulkRowsContainer.appendChild(item);
    }
}


// -----------------------------
// Quantity Change
// -----------------------------

bulkCountInput.addEventListener(
    "change",
    generateBulkTransactionRows
);
bulkCountInput.addEventListener(
    "input",
    generateBulkTransactionRows
);


// -----------------------------
// CREATE ALL TRANSACTIONS
// -----------------------------

bulkCreateBtn.addEventListener(
    "click",
    () => {
        const items =
            bulkRowsContainer.querySelectorAll(
                ".txBulkTransactionItem"
            );
        if (!items.length) {
            alert("Pehle transactions generate karo.");
            return;
        }
        const transactions = [];
        // -----------------------------
        // Read Every Transaction
        // -----------------------------
        for (let i = 0; i < items.length; i++) {
            const item = items[i];
            const id =
                item.querySelector(
                    ".txBulkRowId"
                ).value.trim();
            const dateValue =
                item.querySelector(
                    ".txBulkRowDate"
                ).value;
            const status =
                item.querySelector(
                    ".txBulkRowStatus"
                ).value;
            const type =
                item.querySelector(
                    ".txBulkRowType"
                ).value;
            const payment =
                item.querySelector(
                    ".txBulkRowPayment"
                ).value;
            const amountValue =
                Number(
                    item.querySelector(
                        ".txBulkRowAmount"
                    ).value
                );
            // Validation
            if (!id) {
                alert(
                    `Transaction ${i + 1}: ID enter karo.`
                );
                return;
            }
            if (!dateValue) {
                alert(
                    `Transaction ${i + 1}: Date & Time select karo.`
                );
                return;
            }
            if (
                !Number.isFinite(amountValue) ||
                amountValue <= 0
            ) {
                alert(
                    `Transaction ${i + 1}: Valid amount enter karo.`
                );
                return;
            }
            // Format Date
            const date =
                formatDate(dateValue);
            // Deposit = +
            // Payout = -
            const sign =
                type === "Deposit"
                    ? "+"
                    : "-";
            const amount =
                sign +
                "$" +
                amountValue.toLocaleString(
                    "en-US",
                    {
                        minimumFractionDigits: 2,
                        maximumFractionDigits: 2
                    }
                );
            transactions.push({
                id: id,
                date: date,
                status: status,
                type: type,
                payment: payment,
                amount: amount
            });
        }
        // -----------------------------
        // Create Every Transaction
        // -----------------------------
        transactions
            .slice()
            .reverse()
            .forEach(tx => {
                const newRow =
                    createTransactionRow(tx);
                const header =
                    list.querySelector(
                        ".transactions-list__header"
                    );
                if (header) {
                    header.insertAdjacentElement(
                        "afterend",
                        newRow
                    );
                } else {
                    list.prepend(newRow);
                }
            });
        // Save All
        saveTransactions();
        // Close Popup
        bulkAddOverlay.style.display =
            "none";
        alert(
            `${transactions.length} different transactions successfully added!`
        );
    }
);


