function formatDate(value) {
    if (!value) return "";
    const [date, time] = value.split("T");
    const [year, month, day] = date.split("-");
    return `${day}/${month}/${year}, ${time}:00`;
}

function startAutoSuccessTimer(row, autoSuccessAt) {
    if (!autoSuccessAt) return;
    const remainingTime =
        Number(autoSuccessAt) - Date.now();
    if (remainingTime <= 0) {
        makeTransactionSuccess(row);
        return;
    }
    setTimeout(() => {
        makeTransactionSuccess(row);
    }, remainingTime);
}


