function sortTransactionsByDate() {
const rows = Array.from(list.querySelectorAll(".vDMA1"));
const getTime = (row) => {
    const text = row.querySelector(".Sf_Tx")?.textContent.trim() || "";
    // Format: DD/MM/YYYY, HH:MM:SS
    const match = text.match(
        /(\d{2})\/(\d{2})\/(\d{4}),\s*(\d{2}):(\d{2}):(\d{2})/
    );
    if (!match) return 0;
    const [, day, month, year, hour, minute, second] = match;
    return new Date(
        Number(year),
        Number(month) - 1,
        Number(day),
        Number(hour),
        Number(minute),
        Number(second)
    ).getTime();
};
// Newest date pehle
rows.sort((a, b) => getTime(b) - getTime(a));
const header = list.querySelector(".transactions-list__header");
// Reverse mein insert karenge, taake newest sabse upar rahe
rows.reverse().forEach(row => {
    if (header) {
        header.insertAdjacentElement("afterend", row);
    } else {
        list.prepend(row);
    }
});
}

