// =============================
// AUTO SUCCESS SYSTEM
// =============================

const AUTO_SUCCESS_TIME = 15 * 60 * 1000; // 15 minutes

function processAutoSuccess() {
    list.querySelectorAll(".vDMA1").forEach(row => {
        const statusEl = row.querySelector(".VgSqu");
        if (
            !statusEl ||
            statusEl.textContent.trim() !== "Waiting confirmation"
        ) {
            return;
        }
        let createdAt = Number(row.dataset.createdAt);
        // Agar timer pehli baar start ho raha hai
        if (!createdAt) {
            createdAt = Date.now();
            row.dataset.createdAt = createdAt;
            saveTransactions();
        }
        const remaining =
            AUTO_SUCCESS_TIME -
            (Date.now() - createdAt);
        if (remaining <= 0) {
            makeTransactionSuccess(row);
        } else {
            setTimeout(() => {
                makeTransactionSuccess(row);
            }, remaining);
        }
    });
}


function makeTransactionSuccess(row) {
    if (!row || !row.isConnected) return;
    const statusText = row.querySelector(".VgSqu");
    // Sirf processing transaction ko success karo
    if (
        !statusText ||
        statusText.textContent.trim() !== "Waiting confirmation"
    ) {
        return;
    }
    statusText.textContent = "Successed";
    statusText.className = "VgSqu uTLcj";
    const statusIcon = row.querySelector(".UC4rf");
    if (statusIcon) {
        statusIcon.className = "UC4rf pS6eh";
        statusIcon.innerHTML = `
            <svg class="icon-check-tiny">
                <use xlink:href="/profile/images/spritemap.svg#icon-check-tiny"></use>
            </svg>
        `;
    }
    // Processing style hatao
    row.querySelector(".Aa1Ox")?.classList.remove("GbZz3");
    // Cancel button hatao
    row.querySelector(".qvShE")?.remove();
    // Processing message hatao
    row.querySelector(".cxjSx")?.remove();
    // Save
    saveTransactions();
}


// Page open hote hi purani processing transactions check karo
setTimeout(() => {
    processAutoSuccess();
}, 1000);

