    // ============================================================  
    // APPLY TRADE COUNT  
    // ============================================================  
    const applyTradeCount = (count) => {  
        const items = document.querySelectorAll('.analytics__profile-statistics__item');  
        for (const item of items) {  
            const label = item.querySelector('.analytics__profile-statistics__item-label');  
            if (label && label.textContent.trim().toLowerCase() === 'trades count') {  
                const money = item.querySelector('.analytics__profile-statistics__item-money') ||   
                             item.querySelector('.analytics__profile-statistics__item-value');  
                if (money) money.textContent = count.toString();  
                break;  
            }  
        }  

        fixTradeCircleGreen();

        const winRate = 87;  
        const winTrades = Math.round((count * winRate) / 100);  
        const lossTrades = count - winTrades;  

        for (const item of items) {  
            const label = item.querySelector('.analytics__profile-statistics__item-label');  
            if (label && label.textContent.trim().toLowerCase() === 'profitable trades') {  
                const money = item.querySelector('.analytics__profile-statistics__item-money') ||   
                             item.querySelector('.analytics__profile-statistics__item-value');  
                if (money) {  
                    money.textContent = winTrades.toString();  
                    const percent = item.querySelector('.analytics__profile-statistics__item-percent');  
                    if (percent) percent.textContent = winRate + '%';  
                }  
                break;  
            }  
        }  

        for (const item of items) {  
            const label = item.querySelector('.analytics__profile-statistics__item-label');  
            if (label && label.textContent.trim().toLowerCase().includes('loss trades')) {  
                const money = item.querySelector('.analytics__profile-statistics__item-money') ||   
                             item.querySelector('.analytics__profile-statistics__item-value');  
                if (money) {  
                    money.textContent = lossTrades.toString();  
                    const percent = item.querySelector('.analytics__profile-statistics__item-percent');  
                    if (percent) percent.textContent = (100 - winRate) + '%';  
                }  
                break;  
            }  
        }  

        saveTradeCount(count);  
        console.log(`✅ Trade Count Applied: ${count} (Win: ${winTrades} | Loss: ${lossTrades})`);  
    };

